	@Test
	void alreadyWholeLeftRightRecipeIsAddedOnceAndRequiresItsExactContextAndPopulation() {
		Fixture f = new Fixture();
		int left = f.program(9, 2.5d, 0.0d);
		PackedCostEstimate source = physical(4.0d, 3.0d, 7.0d);
		int right = f.completions.completeProgram(f.vectors.importEstimate(source), 12, 10.0d, 9.0d);
		int input = f.completions.source(f.vectors.importEstimate(source), 5, left, 12, 10.0d, source, false);
		PackedCostEstimate local = physical(1.0d, 0.0d, 0.0d);
		int vector = f.vectors.importEstimate(local);
		int complete = f.completions.completeBinary(vector, local, left, right, 5, input,
				PackedPhysicalJoinCosting.DEPENDENT_ITERATION, 1.0d, 123.5d);
		assertEquals(5.0d,
				f.vectors.point(f.completions.vectorId(complete), PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
		int wrongPopulation = f.completions.completeProgram(f.vectors.importEstimate(source), 12, 1.0d, 9.0d);
		int wrongContext = f.completions.completeProgram(f.vectors.importEstimate(source), 13, 10.0d, 9.0d);
		for (int wrong : new int[] { wrongPopulation, wrongContext }) {
			int refused = f.completions.completeBinary(vector, local, left, wrong, 5, input,
					PackedPhysicalJoinCosting.DEPENDENT_ITERATION, 1.0d, 123.5d);
			assertFalse(
					f.vectors.isKnown(f.completions.vectorId(refused), PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
		}
		int twice = f.completions.completeBinary(vector, local, left, right, 5, input,
				PackedPhysicalJoinCosting.DEPENDENT_ITERATION, 2.0d, 123.5d);
		assertFalse(f.vectors.isKnown(f.completions.vectorId(twice), PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
	}

