	@Test
	void completeProgramIdentityKeepsOnlyNumericCostsAndRealDomains() {
		Fixture f = new Fixture();
		int vector = f.vectors.importEstimate(physical(4.0d, 3.0d, 7.0d));
		int first = f.completions.completeProgram(vector, 3, 2.5d, 9.0d);
		assertEquals(first, f.completions.completeProgram(vector, 3, 2.5d, 9.0d));
		int context = f.completions.completeProgram(vector, 4, 2.5d, 9.0d);
		int population = f.completions.completeProgram(vector, 3, 1.0d, 9.0d);
		assertNotEquals(first, context);
		assertNotEquals(first, population);
		assertFalse(f.completions.comparable(first, context));
		assertFalse(f.completions.comparable(first, population));
		int differentObjective = f.completions.completeProgram(vector, 3, 2.5d, 11.0d);
		assertNotEquals(first, differentObjective);
		assertEquals(11.0d, f.completions.objective(differentObjective));
		assertEquals(f.completions.vectorId(first), f.completions.vectorId(differentObjective));
	}

	@Test
	void activeInputFrameChecksOrderedRelationsRowsAndExactStateWithoutRetainingHistory() {
		PackedQuery query = query();
		try (PackedMemo memo = memo(query)) {
			PackedCostEstimate source = physical(4.0d, 3.0d, 7.0d);
			PackedCostContext context = new PackedCostContext();
			context.reset(new int[] { 1, 2 }, 0, 2, 2.5d, 19);
			int frame = memo.captureFactorPhysicalCost(source, context, 0, 0, true);
			assertTrue(memo.matchesCostInputLeft(frame, new int[] { 1, 2 }, 2, 2.5d, 19));
			assertFalse(memo.matchesCostInputLeft(frame, new int[] { 2, 1 }, 2, 2.5d, 19));
			assertFalse(memo.matchesCostInputLeft(frame, new int[] { 1, 2 }, 2, 2.0d, 19));
			assertFalse(memo.matchesCostInputLeft(frame, new int[] { 1, 2 }, 2, 2.5d, 18));
			memo.captureFactorPhysicalCost(source, context, 0, 0, true);
			assertFalse(memo.matchesCostInputLeft(frame, new int[] { 1, 2 }, 2, 2.5d, 19));
		}
	}

	@Test
	void plannerWitnessSurvivesCandidateCopyButNotProviderCopyMutationOrAnotherQuery() {
		PackedQuery query = query();
		try (PackedMemo first = memo(query); PackedMemo second = memo(query)) {
			PackedCostEstimate source = physical(4.0d, 3.0d, 7.0d);
			PackedCostContext context = new PackedCostContext();
			context.reset(new int[] { 1 }, 0, 1, 2.5d);
			first.captureFactorPhysicalCost(source, context, 0, 0, true);
			int certificate = first.plannerCostCompletionId(source);
			assertNotEquals(0, certificate);
			PackedCostEstimate candidate = new PackedCostEstimate();
			candidate.copyCandidateFrom(source);
			assertEquals(certificate, first.plannerCostCompletionId(candidate));
			assertEquals(0, second.plannerCostCompletionId(candidate));
			PackedCostEstimate provider = new PackedCostEstimate();
			provider.copyProviderInputFrom(source);
			assertEquals(0, first.plannerCostCompletionId(provider));
			candidate.setInvocations(5.0d);
			assertEquals(0, first.plannerCostCompletionId(candidate));
			candidate.copyCandidateFrom(source);
			candidate.setComponentOutputRowsPreservingPhysicalCost(candidate.outputRows());
			assertEquals(0, first.plannerCostCompletionId(candidate));
			candidate.copyCandidateFrom(source);
			candidate.setLocalPhysicalCost(9.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			assertEquals(0, first.plannerCostCompletionId(candidate));
		}
	}

	@Test
	void physicalMetadataRetainsExplicitScalarScopeAndTypedProfilePopulationIndependently() {
		PackedPhysicalMetadataArena metadata = new PackedPhysicalMetadataArena(2);
		PackedCostEstimate scalar = new PackedCostEstimate();
		scalar.setContextualRows(128.0d, 1.0d);
		int scalarId = metadata.append(scalar, 128.0d, 1.0d);
		assertTrue(metadata.hasContextualScalarWork(scalarId));
		assertTrue(Double.isNaN(metadata.dependentInvocationCount(scalarId)));
		assertEquals(1.0d, metadata.invocations(scalarId));
		PackedCostEstimate typed = physical(4.0d, 3.0d, 7.0d);
		typed.setDependentCostComponents(2.0d, 4.0d, 1.0d, 3.0d, 3.0d, 1.0d, 1.0d,
				5.0d, 1.0d, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d);
		int typedId = metadata.append(typed, typed.outputRows(), typed.workRows());
		assertFalse(metadata.hasContextualScalarWork(typedId));
		assertEquals(4.0d, metadata.dependentInvocationCount(typedId));
		assertEquals(1.0d, metadata.invocations(typedId));
	}

	@Test
	void completionStorageReservesExactPrimitiveCapacityBeforeGrowthAndRefusesExhaustion() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedCostVectorArena vectors = new PackedCostVectorArena(budget);
		int vector = vectors.importEstimate(physical(0.0d, 0.0d, 0.0d));
		long before = budget.retainedBytes();
		PackedCostCompletionArena completions = new PackedCostCompletionArena(budget, vectors,
				new PackedCostAlgebra(vectors));
		assertEquals(520L, budget.retainedBytes() - before);
		long initial = budget.retainedBytes();
		for (int context = 0; context < 20; context++) {
			assertTrue(completions.completeProgram(vector, context, 1.0d, 9.0d) > 0);
		}
		assertEquals(512L, budget.retainedBytes() - initial);
		PackedSearchBudget exhausted = new PackedSearchBudget(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, 0L));
		PackedCostVectorArena unavailable = new PackedCostVectorArena(exhausted);
		PackedCostCompletionArena refused = new PackedCostCompletionArena(exhausted, unavailable,
				new PackedCostAlgebra(unavailable));
		assertEquals(0, refused.withObjective(0, 1.0d));
		assertEquals(0L, exhausted.retainedBytes());
		assertTrue(exhausted.resourceLimitReached());
	}

	private static PackedCostEstimate physical(double scans, double results, double peak) {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(results, scans);
		estimate.setLocalPhysicalCost(scans, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, results, 0.0d, peak);
		return estimate;
	}

	private static PackedQuery query() {
		return PackedQueryCodec.encodeForPlanning(new StatementPattern(new Var("s"), new Var("p"), new Var("o")));
	}

	private static PackedMemo memo(PackedQuery query) {
		return new PackedMemo(query, query.symbolCount(), 4, 4, 4, 4, 4);
	}

	private static final class Fixture {
		private final PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		private final PackedCostVectorArena vectors = new PackedCostVectorArena(budget);
		private final PackedCostCompletionArena completions = new PackedCostCompletionArena(budget, vectors,
				new PackedCostAlgebra(vectors));

		private int program(int context, double population, double work) {
			vectors.resetBuilderToZero();
			vectors.setBuilderExact(PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK, work);
			return completions.completeProgram(vectors.internBuilder(), context, population, work);
		}
	}
